provider "aws" {
  region     = "us-east-1"
}

resource "aws_glacier_vault" "example" {
  name = "example"
}

data "aws_iam_policy_document" "example" {
  statement {
    actions   = ["glacier:DeleteArchive"]
    effect    = "Deny"
    resources = [aws_glacier_vault.example.arn]

    condition {
      test     = "NumericLessThanEquals"
      variable = "glacier:ArchiveAgeinDays"
      values   = ["365"]
    }
  }
}

resource "aws_glacier_vault_lock" "example" {
  complete_lock = false
  policy        = data.aws_iam_policy_document.example.json
  vault_name    = aws_glacier_vault.example.name
}

responsePreview:
This Terraform configuration creates an AWS S3 Glacier Vault and applies a Glacier Vault Lock policy that enforces a minimum archive retention period. By default, the lock is initiated but not permanently completed, because completing a Vault Lock is irreversible. To permanently lock the policy, set `complete_vault_lock = true`.

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region where the Glacier vault will be created."
  type        = string
  default     = "us-east-1"
}

variable "vault_name" {
  description = "Name of the S3 Glacier vault."
  type        = string
  default     = "example-glacier-vault-with-lock"
}

variable "minimum_retention_days" {
  description = "Minimum number of days archives must be retained before they can be deleted."
  type        = number
  default     = 365
}

variable "complete_vault_lock" {
  description = "Whether to permanently complete the Glacier Vault Lock. WARNING: This is irreversible."
  type        = bool
  default     = false
}

